import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.7R1OEGYz.js";const g=JSON.parse('{"title":"Pilot setup","description":"","frontmatter":{},"headers":[],"relativePath":"pilot-setup.md","filePath":"pilot-setup.md","lastUpdated":null}'),n={name:"pilot-setup.md"};function o(r,e,h,l,d,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="pilot-setup" tabindex="-1">Pilot setup <a class="header-anchor" href="#pilot-setup" aria-label="Permalink to &quot;Pilot setup&quot;">​</a></h1><p>This page takes a pilot team from an empty host to a running instance with team login and, if your pilot includes it, an active Enterprise licence. It collects the steps in the order that avoids the known traps; the linked pages hold the details.</p><p><strong>Edition:</strong> Community (install, team login, admins) · Enterprise (licence and the features it unlocks) · <strong>Who:</strong> the operator who installs the chart and the first administrator</p><p>Placeholders in capitals, such as <code>YOUR_HOST</code> or <code>YOUR_USERNAME</code>, stand for your own values.</p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><p>Pick one of the two paths on <a href="/docs/getting-started">Install</a>. Both install the current release.</p><table tabindex="0"><thead><tr><th>Path</th><th>When</th><th>Command</th></tr></thead><tbody><tr><td>Quickstart</td><td>One Linux host, or Docker Desktop on macOS or Windows, without an existing cluster</td><td><code>curl -fsSL https://open-agenthub.github.io/install.sh | sh</code> (Windows: <code>install.ps1</code>)</td></tr><tr><td>Helm</td><td>You already run Kubernetes</td><td><code>helm repo add agenthub https://open-agenthub.github.io/open-agenthub</code>, then <code>helm install</code> as shown on <a href="/docs/getting-started#you-have-a-kubernetes-cluster">Install</a></td></tr></tbody></table><p>The quickstart sets up persistent Postgres and object storage for you. With Helm, configure object storage as well (<code>s3.*</code>, or <code>objectStorage.enabled=true</code>): without it, sessions cannot resume in a fresh pod and uploaded files disappear with the pod.</p><p>For a pilot that may run longer than a test, prefer your own Postgres (<code>postgres.enabled=false</code> and <code>externalDatabase.connectionString</code>); the bundled one is meant for evaluation. Keep all settings in one values file from the start, such as <code>my-values.yaml</code>, and pass it to every <code>helm upgrade</code> with <code>-f</code>. That file holds secrets: keep it out of version control.</p><p>The <a href="/docs/evaluate">evaluation checklist</a> lists what to prepare (hostname, TLS certificate, identity provider, Git access, a model account) and how long each step took when we measured it.</p><h2 id="_2-team-login-oidc" tabindex="-1">2. Team login (OIDC) <a class="header-anchor" href="#_2-team-login-oidc" aria-label="Permalink to &quot;2. Team login (OIDC)&quot;">​</a></h2><p>Without an identity provider the instance runs with one generated API key that acts as an administrator. For a team, switch to OIDC. Do it in this order:</p><ol><li><p><strong>Choose the first administrator.</strong> Under OIDC nobody is an administrator until one is named. Use that person&#39;s sign-in name as your identity provider issues it in the <code>preferred_username</code> claim.</p></li><li><p><strong>Register the client</strong> at your identity provider: a public client with Authorization Code Flow and PKCE, redirect URI <code>https://YOUR_HOST/auth/callback</code>, post-logout redirect <code>https://YOUR_HOST</code>, web origin <code>https://YOUR_HOST</code>, JWT access tokens for your audience, and refresh tokens (<code>offline_access</code>). <a href="/docs/getting-started#_2-sign-in">Install → Sign in</a> lists every requirement.</p></li><li><p><strong>Set the administrator and the OIDC values in the same upgrade</strong>, so there is no moment in which the instance has team login but no administrator:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># my-values.yaml (excerpt)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ingress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_HOST</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tlsSecretName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_TLS_SECRET</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontendOrigin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://YOUR_HOST</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">oidc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://YOUR_ISSUER</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  clientId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agenthub</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  audience</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agenthub</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ee</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  admins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_USERNAME&quot;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5m</span></span></code></pre></div></li><li><p><strong>Sign in as that administrator first</strong>, before you share the URL. Then promote further administrators under <strong>Settings → Users &amp; seats → Admins &amp; roles</strong>.</p></li></ol><p><code>ee.admins</code> takes comma-separated names. Names listed there cannot be demoted in the app, so they remain a way back in if role settings go wrong. Despite the <code>ee.</code> prefix, the value works in both editions. Groups from your identity provider can grant the admin role only with an Enterprise licence; keep at least one name in <code>ee.admins</code> as a fallback.</p><p>Data created while the API key was in use belongs to the key&#39;s user name and becomes visible to an OIDC user with the same name. Read <a href="/docs/admin#switching-from-the-api-key-to-oidc">Switching from the API key to OIDC</a> before you switch. If your identity provider uses a certificate from an internal certificate authority, see <a href="/docs/getting-started#move-the-quickstart-to-team-login">team login</a> for <code>backend.trustedCaConfigMap</code>.</p><h2 id="_3-enterprise-licence" tabindex="-1">3. Enterprise licence <a class="header-anchor" href="#_3-enterprise-licence" aria-label="Permalink to &quot;3. Enterprise licence&quot;">​</a></h2><p><strong>Enterprise.</strong> The Community edition is fully usable without a licence. A licence unlocks the Enterprise features: sharing, group roles, usage limits, the agent allowlist, Slack and the others marked Enterprise in the <a href="/docs/features">feature overview</a>.</p><p>The licence is a signed token. The instance verifies it offline and stores it in its database. No chart value switches Enterprise features on.</p><h3 id="how-an-instance-gets-a-licence" tabindex="-1">How an instance gets a licence <a class="header-anchor" href="#how-an-instance-gets-a-licence" aria-label="Permalink to &quot;How an instance gets a licence&quot;">​</a></h3><p>An administrator opens <strong>Settings → License</strong>. There are two ways to a token:</p><table tabindex="0"><thead><tr><th>Way</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Issued to you</strong></td><td>For a pilot or a contract with manual invoicing, the licence is issued for your organisation and the token is sent to you. Paste it into <strong>License token</strong> and click <strong>Activate</strong>.</td></tr><tr><td><strong>Checkout</strong></td><td><strong>Get enterprise license</strong> asks for billing email, organisation and seats and redirects to the payment provider. Afterwards the instance comes back to <code>https://YOUR_HOST/license/activate</code> and activates the licence itself. If that return did not happen, <strong>Retrieve license</strong> with the same billing email activates a licence that has been paid but not yet activated. The checkout page shows the price and terms that apply before you pay.</td></tr></tbody></table><p>Only an administrator sees <strong>Settings → License</strong>.</p><h3 id="licence-status" tabindex="-1">Licence status <a class="header-anchor" href="#licence-status" aria-label="Permalink to &quot;Licence status&quot;">​</a></h3><p>After activation the <strong>Enterprise license</strong> card shows:</p><ul><li>a badge: <strong>active</strong>, <strong>invalid</strong> (a token is stored but does not verify or has expired) or <strong>not activated</strong>;</li><li><strong>Plan</strong>, <strong>Organization</strong> and <strong>Seats included</strong>;</li><li><strong>Valid until</strong> for a licence with a fixed end, otherwise <strong>Renewal: automatic</strong>;</li><li><strong>Last successful report</strong>, <strong>Enterprise features stop without renewal</strong> and <strong>Last report error</strong>.</li></ul><p>The instance renews its token by reporting to the licence service, normally once every 24 hours. The report contains the token and an aggregate count of licensed users, nothing else. The backend needs outbound HTTPS to the licence service for this (chart value <code>ee.license.serviceUrl</code>; an empty value disables reporting). If renewal keeps failing, Enterprise features stop at the date shown on the card; Community features keep working. An admin warning appears seven days before that date. See <a href="/docs/admin#check-renewal-health">Check renewal health</a>.</p><p>Every user who signs in gets a seat. <strong>Settings → Users &amp; seats</strong> shows the seats in use against the seats included; untick a user to free a seat.</p><h3 id="manual-invoicing" tabindex="-1">Manual invoicing <a class="header-anchor" href="#manual-invoicing" aria-label="Permalink to &quot;Manual invoicing&quot;">​</a></h3><p>If your organisation does not pay through the online checkout, the licence is issued to you and you are invoiced separately.</p><div class="info custom-block"><p class="custom-block-title">Terms: per your order form</p><p>Invoicing interval, payment terms, seat count, how seat changes are invoiced, and the licence term are set by your order form. This page does not describe them.</p></div><p>With manual invoicing, <strong>Settings → Billing &amp; invoices</strong> may not apply to you: invoices come the way your order form says. The seat count the instance reports is visible under <strong>Settings → Users &amp; seats</strong>.</p><h2 id="_4-before-the-team-starts" tabindex="-1">4. Before the team starts <a class="header-anchor" href="#_4-before-the-team-starts" aria-label="Permalink to &quot;4. Before the team starts&quot;">​</a></h2><ul><li><strong>Back up</strong> the database and the Secret <code>agenthub-data-protection</code> from the first day; the stored secrets cannot be decrypted without that Secret. See <a href="/docs/upgrading#before-every-upgrade">Before every upgrade</a> for the commands.</li><li><strong>Leave experimental features off.</strong> <code>agent.workspaceVolume.persistent</code> (the provider switch) stays <code>false</code>, the chart default.</li><li><strong>Agree how you will upgrade.</strong> Read <a href="/docs/upgrading">Upgrading</a> and plan the first upgrade before you need it.</li><li><strong>Know where to get help.</strong> See <a href="/docs/support">Support</a>.</li></ul>`,33)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
